-- PostgreSQL 18.4, Docker arm64; generated dependencies after immutable function replacement.
CREATE SCHEMA generated_dependencies;
CREATE FUNCTION generated_dependencies.g(value int) RETURNS int LANGUAGE SQL IMMUTABLE AS 'SELECT value';
CREATE FUNCTION generated_dependencies.keep_row() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NEW; END';
CREATE TABLE generated_dependencies.parent(id int PRIMARY KEY);
INSERT INTO generated_dependencies.parent VALUES (1);
CREATE TABLE generated_dependencies.ordinary(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.ordinary VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.defaulted(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.defaulted VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.before_row(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.before_row VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.disabled(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.disabled VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.column_trigger(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.column_trigger VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.merge(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.merge VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.conflict(id int PRIMARY KEY, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.conflict VALUES(1,7,0,DEFAULT);
CREATE TABLE generated_dependencies.referential(id int PRIMARY KEY REFERENCES generated_dependencies.parent(id) ON UPDATE CASCADE, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED);
INSERT INTO generated_dependencies.referential VALUES(1,7,0,DEFAULT);
CREATE TRIGGER keep_row BEFORE UPDATE ON generated_dependencies.before_row FOR EACH ROW EXECUTE FUNCTION generated_dependencies.keep_row();
CREATE TRIGGER keep_row BEFORE UPDATE ON generated_dependencies.disabled FOR EACH ROW EXECUTE FUNCTION generated_dependencies.keep_row();
CREATE TRIGGER keep_row BEFORE UPDATE OF source ON generated_dependencies.column_trigger FOR EACH ROW EXECUTE FUNCTION generated_dependencies.keep_row();
ALTER TABLE generated_dependencies.disabled DISABLE TRIGGER keep_row;
CREATE TABLE generated_dependencies.partitioned(id int, source int, unrelated int, stored int GENERATED ALWAYS AS(generated_dependencies.g(source)) STORED) PARTITION BY RANGE(id);
CREATE TABLE generated_dependencies.low PARTITION OF generated_dependencies.partitioned FOR VALUES FROM(0) TO(10);
CREATE TABLE generated_dependencies.high PARTITION OF generated_dependencies.partitioned FOR VALUES FROM(10) TO(20);
ALTER TABLE generated_dependencies.high ALTER COLUMN stored SET EXPRESSION AS(generated_dependencies.g(source)+1000);
ALTER TABLE generated_dependencies.high ADD CHECK(stored=source+1100);
INSERT INTO generated_dependencies.partitioned VALUES(1,7,0,DEFAULT),(2,8,0,DEFAULT);
CREATE FUNCTION generated_dependencies.change_input() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN NEW.source := NEW.source+1; RETURN NEW; END';
CREATE TRIGGER change_input BEFORE INSERT ON generated_dependencies.high FOR EACH ROW WHEN(NEW.id=12) EXECUTE FUNCTION generated_dependencies.change_input();
CREATE OR REPLACE FUNCTION generated_dependencies.g(value int) RETURNS int LANGUAGE SQL IMMUTABLE AS 'SELECT value + 100';
UPDATE generated_dependencies.ordinary SET unrelated=unrelated+1;
UPDATE generated_dependencies.before_row SET unrelated=unrelated+1;
UPDATE generated_dependencies.disabled SET unrelated=unrelated+1;
UPDATE generated_dependencies.column_trigger SET unrelated=unrelated+1;
UPDATE generated_dependencies.defaulted SET stored=DEFAULT;
MERGE INTO generated_dependencies.merge t USING (VALUES (1)) s(id) ON t.id=s.id WHEN MATCHED AND s.id=1 THEN UPDATE SET unrelated=unrelated+1 WHEN MATCHED THEN UPDATE SET source=source;
INSERT INTO generated_dependencies.conflict VALUES(1,7,10,DEFAULT) ON CONFLICT(id) DO UPDATE SET unrelated=excluded.unrelated;
UPDATE generated_dependencies.parent SET id=2 WHERE id=1;
UPDATE generated_dependencies.partitioned SET id=id+10;
SELECT 'ordinary' AS step,id,source,unrelated,stored FROM generated_dependencies.ordinary UNION ALL SELECT 'defaulted' AS step,id,source,unrelated,stored FROM generated_dependencies.defaulted UNION ALL SELECT 'before_row' AS step,id,source,unrelated,stored FROM generated_dependencies.before_row UNION ALL SELECT 'disabled' AS step,id,source,unrelated,stored FROM generated_dependencies.disabled UNION ALL SELECT 'column_trigger' AS step,id,source,unrelated,stored FROM generated_dependencies.column_trigger UNION ALL SELECT 'merge' AS step,id,source,unrelated,stored FROM generated_dependencies.merge UNION ALL SELECT 'conflict' AS step,id,source,unrelated,stored FROM generated_dependencies.conflict UNION ALL SELECT 'referential' AS step,id,source,unrelated,stored FROM generated_dependencies.referential UNION ALL SELECT 'partition' AS step,id,source,unrelated,stored FROM generated_dependencies.partitioned WHERE id=11 UNION ALL SELECT 'partition_trigger' AS step,id,source,unrelated,stored FROM generated_dependencies.partitioned WHERE id=12 ORDER BY step;
